-- ~/.config/nvim/colors/kawa.lua — kawa, the desktop's colour scheme. Generated by
-- tools/build-themes.py; edit the palette there. Both moods live here; 'background' (which
-- Neovim has from foot, and again whenever kawa-theme switches) picks the one drawn.
-- No italics: Sumi Term has one upright face, and a slanted copy of a dot font smears.
local inks = {
  dark = {
    bg = "#181715",
    float = "#1c1916",
    key = "#221e1a",
    line = "#221e1a",
    edge = "#2d251e",
    edge2 = "#3c2f22",
    text = "#e7cfa1",
    strong = "#f5ecc2",
