    yellow = "#e2b540",
    fn = "#e2b540",
    green = "#8fa071",
    aqua = "#82c1b4",
    blue = "#a7d4e4",
    purple = "#b5b1d8",
    accent = "#eb5324",
    on_accent = "#111314",
    cursorline = "#2d251e",
    sel = "#46271d",
    sel_text = "#f8a17a",
    add = "#96d1aa",
    del = "#f58e84",
    chg = "#e2b540",
    addbg = "#2c352d",
    delbg = "#3b2a27",
    chgbg = "#38301c",
    textbg = "#405345",
    ansi = { "#2d251e","#eb5324","#8fa071","#e2b540","#97acc8","#9a72aa","#00978d","#e7cfa1","#cab596","#f58e84","#96d1aa","#fbe6a0","#a7d4e4","#b5b1d8","#62c6bf","#f5ecc2" },
  },
  light = {
    bg = "#e8e3c2",
    float = "#ecdfb3",
    key = "#f8f3d8",
    line = "#dfcc9c",
    edge = "#dfcc9c",
    edge2 = "#d7bc8c",
    text = "#122625",
    strong = "#121b1b",
    muted = "#586459",
    faint = "#8b917f",
    comment = "#586459",
    red = "#a84222",
    kw = "#a84222",
    orange = "#bb542d",
    yellow = "#986f2d",
    fn = "#644b1e",
    green = "#437742",
    aqua = "#00726a",
    blue = "#006eb8",
    purple = "#66629c",
    accent = "#a84222",
    on_accent = "#f8f3d8",
    cursorline = "#ecdfb3",
    sel = "#dcbd9b",
    sel_text = "#713724",
    add = "#437742",
    del = "#a84222",
    chg = "#986f2d",
    addbg = "#ced2ae",
    delbg = "#dec9a8",
    chgbg = "#dbd0aa",
    textbg = "#b3c099",
    ansi = { "#e2cfa0","#a84222","#437742","#986f2d","#006eb8","#66629c","#004f46","#122625","#586459","#82241f","#1a7444","#644b1e","#005b8d","#4f4086","#064f6e","#121b1b" },
  },
}
local c = inks[vim.o.background == "light" and "light" or "dark"]

vim.cmd("highlight clear")
if vim.fn.exists("syntax_on") == 1 then vim.cmd("syntax reset") end
vim.g.colors_name = "kawa"
vim.o.termguicolors = true

for i, col in ipairs(c.ansi) do vim.g["terminal_color_" .. (i - 1)] = col end

local function hl(name, spec) vim.api.nvim_set_hl(0, name, spec) end
local function fg(name, col, extra) hl(name, vim.tbl_extend("force", { fg = col }, extra or {})) end
local function link(from, to) hl(from, { link = to, default = false }) end

-- the page: no ground (foot's), text, the cursor's line, the edges
hl("Normal", { fg = c.text })
hl("NormalNC", { fg = c.text })
hl("NormalFloat", { fg = c.text, bg = c.float })
hl("FloatBorder", { fg = c.edge2, bg = c.float })
hl("FloatTitle", { fg = c.strong, bg = c.float, bold = true })
hl("FloatFooter", { fg = c.muted, bg = c.float })
hl("Cursor", { fg = c.bg, bg = c.text })
link("lCursor", "Cursor"); link("CursorIM", "Cursor"); link("TermCursor", "Cursor")
hl("CursorLine", { bg = c.cursorline })
hl("ColorColumn", { bg = c.cursorline })
hl("CursorColumn", { bg = c.cursorline })
fg("CursorLineNr", c.accent, { bold = true })
fg("LineNr", c.faint)
fg("LineNrAbove", c.faint); fg("LineNrBelow", c.faint)
hl("SignColumn", {})
hl("FoldColumn", { fg = c.faint })
hl("Folded", { fg = c.muted, bg = c.line })
fg("NonText", c.edge2); fg("EndOfBuffer", c.bg)
fg("Whitespace", c.edge2); fg("SpecialKey", c.edge2)
fg("Conceal", c.muted)
fg("Directory", c.aqua)
fg("VertSplit", c.edge2); fg("WinSeparator", c.edge2)
hl("Visual", { bg = c.edge2 })
hl("VisualNOS", { bg = c.edge2 })
hl("Search", { fg = c.bg, bg = c.yellow })
hl("CurSearch", { fg = c.on_accent, bg = c.accent, bold = true })
hl("IncSearch", { fg = c.on_accent, bg = c.accent, bold = true })
hl("Substitute", { fg = c.bg, bg = c.orange })
hl("MatchParen", { bg = c.edge2, bold = true })
fg("ErrorMsg", c.red, { bold = true }); fg("WarningMsg", c.yellow, { bold = true })
fg("MoreMsg", c.green, { bold = true }); fg("ModeMsg", c.muted, { bold = true })
fg("Question", c.orange, { bold = true })
fg("Title", c.accent, { bold = true })
fg("QuickFixLine", c.strong, { bold = true })
hl("WinBar", { fg = c.muted }); hl("WinBarNC", { fg = c.faint })
hl("TabLine", { fg = c.muted, bg = c.line }); hl("TabLineFill", { bg = c.line })
hl("TabLineSel", { fg = c.strong, bg = c.bg, bold = true })
hl("StatusLine", { fg = c.muted, bg = c.line }); hl("StatusLineNC", { fg = c.muted, bg = c.line })
hl("Pmenu", { fg = c.text, bg = c.float })
hl("PmenuSel", { fg = c.sel_text, bg = c.sel })
hl("PmenuSbar", { bg = c.float }); hl("PmenuThumb", { bg = c.edge2 })
hl("PmenuKind", { fg = c.aqua, bg = c.float }); hl("PmenuExtra", { fg = c.muted, bg = c.float })
hl("WildMenu", { fg = c.sel_text, bg = c.sel })
hl("SpellBad", { sp = c.red, undercurl = true }); hl("SpellCap", { sp = c.yellow, undercurl = true })
hl("SpellLocal", { sp = c.aqua, undercurl = true }); hl("SpellRare", { sp = c.purple, undercurl = true })

-- diffs
hl("DiffAdd", { bg = c.addbg }); hl("DiffChange", { bg = c.chgbg })
hl("DiffDelete", { fg = c.del, bg = c.delbg }); hl("DiffText", { bg = c.textbg })
fg("Added", c.add); fg("Changed", c.chg); fg("Removed", c.del)
fg("diffAdded", c.add); fg("diffRemoved", c.del); fg("diffChanged", c.chg)
fg("diffFile", c.aqua); fg("diffLine", c.muted); fg("diffIndexLine", c.muted)

-- the code: keywords vermilion, functions gold, strings green, types asagi, constants purple,
-- specials orange, operators and punctuation in the quiet ink
fg("Comment", c.comment)
fg("Constant", c.purple); fg("String", c.green); fg("Character", c.green)
fg("Number", c.purple); fg("Boolean", c.purple); fg("Float", c.purple)
fg("Identifier", c.text); fg("Function", c.fn)
fg("Statement", c.kw); fg("Conditional", c.kw); fg("Repeat", c.kw); fg("Label", c.kw)
fg("Keyword", c.kw); fg("Exception", c.kw); fg("Operator", c.muted)
fg("PreProc", c.aqua); fg("Include", c.aqua); fg("Define", c.aqua); fg("Macro", c.aqua)
fg("PreCondit", c.aqua)
fg("Type", c.aqua); fg("StorageClass", c.orange); fg("Structure", c.aqua); fg("Typedef", c.aqua)
fg("Special", c.orange); fg("SpecialChar", c.orange); fg("Tag", c.orange)
fg("Delimiter", c.muted); fg("SpecialComment", c.muted); fg("Debug", c.orange)
hl("Underlined", { fg = c.blue, underline = true })
hl("Ignore", { fg = c.faint })
hl("Error", { fg = c.red, bold = true })
fg("Todo", c.strong, { bold = true, bg = c.line })

-- tree-sitter and the language server
local ts = {
  ["@variable"] = "Identifier", ["@variable.builtin"] = "Special", ["@variable.parameter"] = "Identifier",
  ["@variable.member"] = "Identifier", ["@constant"] = "Constant", ["@constant.builtin"] = "Constant",
  ["@constant.macro"] = "Macro", ["@module"] = "Include", ["@label"] = "Label",
  ["@string"] = "String", ["@string.escape"] = "SpecialChar", ["@string.regexp"] = "SpecialChar",
  ["@string.special"] = "SpecialChar", ["@character"] = "Character", ["@number"] = "Number",
  ["@boolean"] = "Boolean", ["@float"] = "Float", ["@function"] = "Function",
  ["@function.builtin"] = "Function", ["@function.call"] = "Function", ["@function.macro"] = "Macro",
  ["@function.method"] = "Function", ["@function.method.call"] = "Function",
  ["@constructor"] = "Type", ["@operator"] = "Operator", ["@keyword"] = "Keyword",
  ["@keyword.function"] = "Keyword", ["@keyword.return"] = "Keyword", ["@keyword.import"] = "Include",
  ["@keyword.conditional"] = "Conditional", ["@keyword.repeat"] = "Repeat",
  ["@keyword.exception"] = "Exception", ["@keyword.operator"] = "Keyword",
  ["@type"] = "Type", ["@type.builtin"] = "Type", ["@type.definition"] = "Typedef",
  ["@attribute"] = "PreProc", ["@property"] = "Identifier", ["@punctuation"] = "Delimiter",
  ["@punctuation.delimiter"] = "Delimiter", ["@punctuation.bracket"] = "Delimiter",
  ["@punctuation.special"] = "Special", ["@comment"] = "Comment", ["@comment.documentation"] = "Comment",
  ["@tag"] = "Tag", ["@tag.attribute"] = "Identifier", ["@tag.delimiter"] = "Delimiter",
  ["@markup.heading"] = "Title", ["@markup.strong"] = "Bold", ["@markup.italic"] = "Italic",
  ["@markup.link"] = "Underlined", ["@markup.link.url"] = "Underlined", ["@markup.raw"] = "String",
  ["@markup.list"] = "Special", ["@diff.plus"] = "Added", ["@diff.minus"] = "Removed",
  ["@diff.delta"] = "Changed",
  ["@lsp.type.comment"] = "", ["@lsp.type.keyword"] = "Keyword", ["@lsp.type.macro"] = "Macro",
}
hl("Bold", { bold = true }); hl("Italic", {})
hl("@markup.heading.1", { fg = c.accent, bold = true })
for from, to in pairs(ts) do if to ~= "" then link(from, to) end end
fg("@comment.error", c.red, { bold = true }); fg("@comment.warning", c.yellow, { bold = true })
fg("@comment.todo", c.strong, { bold = true }); fg("@comment.note", c.aqua, { bold = true })

local sev = { Error = c.red, Warn = c.yellow, Info = c.aqua, Hint = c.muted, Ok = c.green }
for k, col in pairs(sev) do
  fg("Diagnostic" .. k, col)
  fg("DiagnosticSign" .. k, col)
  fg("DiagnosticVirtualText" .. k, c.muted)
  hl("DiagnosticUnderline" .. k, { sp = col, underline = true })
end
hl("DiagnosticUnnecessary", { fg = c.faint })
hl("LspReferenceText", { bg = c.edge }); hl("LspReferenceRead", { bg = c.edge })
hl("LspReferenceWrite", { bg = c.edge, bold = true })
fg("LspInlayHint", c.faint, { bg = c.line })
fg("LspCodeLens", c.faint)
fg("LspSignatureActiveParameter", c.accent, { bold = true })

-- gitsigns, the picker and dashboard (snacks), the debugger, health
fg("GitSignsAdd", c.add); fg("GitSignsChange", c.chg); fg("GitSignsDelete", c.del)
fg("GitSignsAddNr", c.add); fg("GitSignsChangeNr", c.chg); fg("GitSignsDeleteNr", c.del)
hl("GitSignsAddLn", { bg = c.addbg }); hl("GitSignsChangeLn", { bg = c.chgbg })
hl("GitSignsDeleteLn", { bg = c.delbg }); fg("GitSignsCurrentLineBlame", c.faint)
hl("SnacksPickerMatch", { fg = c.accent, bold = true })
fg("SnacksPickerDir", c.muted); fg("SnacksPickerPathHidden", c.muted)
fg("SnacksPickerPathIgnored", c.faint); fg("SnacksPickerTotals", c.comment)
hl("SnacksPickerBorder", { fg = c.edge2, bg = c.float }); hl("SnacksPickerTitle", { fg = c.strong, bg = c.float, bold = true })
fg("SnacksIndent", c.edge); fg("SnacksIndentScope", c.edge2)
fg("SnacksNotifierInfo", c.text); fg("SnacksNotifierWarn", c.yellow); fg("SnacksNotifierError", c.red)
fg("DapBreakpoint", c.red); fg("DapBreakpointCondition", c.yellow); fg("DapLogPoint", c.aqua)
fg("DapStopped", c.green); hl("DapStoppedLine", { bg = c.addbg })
fg("healthSuccess", c.green); fg("healthWarning", c.yellow); fg("healthError", c.red)
